document.addEventListener('DOMContentLoaded', function(){

    eventListeners();
    darkMode();

});

function darkMode(){

    const botonDarkMode = document.querySelector('.dark-mode-boton');
    const prefiereDarkMode = window.matchMedia('(prefers-color-scheme: dark)');
    const darkModeGuardado = localStorage.getItem('dark-mode');

    // 1️⃣ Revisar si el usuario ya eligió antes
    if(darkModeGuardado !== null){

        if(darkModeGuardado === 'true'){
            document.documentElement.classList.add('dark-mode');
        }

    } else {

        // 2️⃣ Si nunca eligió, usar preferencia del sistema
        if(prefiereDarkMode.matches){
            document.documentElement.classList.add('dark-mode');
        }

    }

    // 3️⃣ Detectar cambios en el sistema
    prefiereDarkMode.addEventListener('change', function(){

        if(localStorage.getItem('dark-mode') === null){
            document.documentElement.classList.toggle('dark-mode', prefiereDarkMode.matches);
        }

    });

    // 4️⃣ Botón para cambiar manualmente
    botonDarkMode.addEventListener('click', function(){

        document.documentElement.classList.toggle('dark-mode');

        if(document.documentElement.classList.contains('dark-mode')){
            localStorage.setItem('dark-mode','true');
        } else {
            localStorage.setItem('dark-mode','false');
        }

    });

}

function eventListeners(){

    const mobileMenu = document.querySelector('.mobile-menu');

    mobileMenu.addEventListener('click', navegacionResponsive);

}

function navegacionResponsive(){

    const navegacion = document.querySelector('.navegacion');

    navegacion.classList.toggle('mostrar');

}